class ValidationException(Exception):
    def __init__(self, errors: Sequence[Any], endpoint_context: Optional[str] = None) -> None:
        self._errors = errors
        self.endpoint_context = endpoint_context

    def errors(self) -> Sequence[Any]:
        return self._errors


class RequestValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None, endpoint_context: Optional[str] = None) -> None:
        super().__init__(errors, endpoint_context=endpoint_context)
        self.body = body


class WebSocketRequestValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], endpoint_context: Optional[str] = None) -> None:
        super().__init__(errors, endpoint_context=endpoint_context)


class ResponseValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None, endpoint_context: Optional[str] = None) -> None:
        super().__init__(errors, endpoint_context=endpoint_context)
        self.body = body

    def __str__(self) -> str:
        message = f"{len(self._errors)} validation errors:\n"
